const event = $input.first().json.event || $input.first().json;
const payload = event.payload || {};

const systemPrompt = `Eres el recomendador de recursos y herramientas de RAX.\nTu función es sugerir metodologías, plantillas o ejercicios prácticos alineados con los desafíos del emprendedor.\nREGLAS:\n1. Explica con claridad por qué el recurso es pertinente para la necesidad detectada y qué limitaciones tiene.\n2. No inventes URLs externas ni enlaces a dominios no verificados.\n3. Formula sugerencias metodológicas reconocidas (Lean Canvas, Customer Discovery, Unit Economics, OKRs).\n4. Salida en JSON estricto con: recommendations (array de objetos con title, kind, rationale, limitations, suggestedExercise), uncertainties (array de strings).`;

const userPrompt = JSON.stringify({
  projectId: event.projectId,
  identifiedProblem: payload.problemTitle || payload.problem || '',
  founderStage: payload.founderStage || 'exploring_idea',
  sector: payload.sector || 'general'
});

return [{
  json: {
    correlationId: event.correlationId || 'corr_' + Date.now(),
    callbackUrl: event.callback?.url || ($env.RAX_API_URL || 'https://rax-red.vercel.app') + '/api/n8n/callback',
    model: $env.OPENROUTER_MODEL || 'meta-llama/llama-3.3-70b-instruct:free',
    apiKey: $env.OPENROUTER_API_KEY || '',
    systemPrompt,
    userPrompt
  }
}];

