const response = $input.first().json;
const prep = $('Build Resources Prompt').first().json;

let parsed = {};
try {
  const content = response.choices?.[0]?.message?.content || '{}';
  parsed = JSON.parse(content);
} catch (e) {
  parsed = { recommendations: [], uncertainties: ['Salida JSON no válida'] };
}

const proposals = (parsed.recommendations || []).map(r => ({
  type: 'recommendation',
  title: r.title,
  description: `${r.rationale} | Ejercicio sugerido: ${r.suggestedExercise || 'N/A'}`,
  needsHumanApproval: true,
  uncertainties: r.limitations ? [r.limitations] : []
}));

const callbackPayload = {
  operationId: 'op_res_' + Date.now(),
  correlationId: prep.correlationId,
  workflowId: 'RAX-11',
  workflowVersion: '1.0.0',
  status: 'completed',
  usage: {
    model: response.model || prep.model,
    promptTokens: response.usage?.prompt_tokens || 0,
    completionTokens: response.usage?.completion_tokens || 0
  },
  data: {
    summary: `Se generaron ${proposals.length} recomendaciones metodológicas.`,
    proposals,
    uncertainties: parsed.uncertainties || []
  }
};

return [{
  json: {
    callbackUrl: prep.callbackUrl,
    payload: callbackPayload
  }
}];

const crypto = require('crypto');
const input = $input.first().json;
const secret = $env.RAX_N8N_SHARED_SECRET;
if (!secret) throw new Error('RAX_N8N_SHARED_SECRET is not configured');
const callbackPayload = input.payload;
if (!callbackPayload || typeof callbackPayload !== 'object') throw new Error('Missing callback payload');
const timestamp = Math.floor(Date.now() / 1000).toString();
const callbackBody = JSON.stringify(callbackPayload);
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + callbackBody).digest('hex');
return [{ json: { ...input, callbackPayload, callbackBody, callbackTimestamp: timestamp, callbackSignature: signature, callbackCorrelationId: callbackPayload.correlationId } }];
